SET NOCOUNT ON;
CREATE TABLE #r (Item nvarchar(100), LegacyValue decimal(38,4), NewValue decimal(38,4));
INSERT #r SELECT 'ModuleTypes rows', (SELECT COUNT(*) FROM [$(Legacy)].dbo.[ModuleTypes]), (SELECT COUNT(*) FROM [ModuleTypes] ) ;
